    predatorExplorationRatio: 0.8, // Bias exploration towards safe lethal maneuvers

    // Dimensions (16 Self/Arena + 17 Enemies x 8 + 8 Platforms x 6 = 200 Features matching 18-player live arena)
    stateDim: 200,
